29	  const sys: Particles = { n, pos: new Float32Array(n * 3), vel: new Float32Array(n * 3), col: new Float32Array(n * 3), size: new Float32Array(n), alpha: new Float32Array(n), life: new Float32Array(n), max: new Float32Array(n), kind: new Uint8Array(n), next: 0, acc: 0, idle: false };
