1	import { clamp, smooth } from '../../common/math';
2	import type { SongHanConfig } from '../../config';
3	
4	/* [swingController] state machine quay cầu, phát event swingStart / swingOpen / swingClosed / stateChange */
5	export const SWING_STATES = ['CLOSED', 'STOP_TRAFFIC', 'UNLOCK', 'ROTATING_OPEN', 'OPEN', 'ROTATING_CLOSE', 'LOCK', 'REOPEN_TRAFFIC'] as const;
6	export type SwingState = typeof SWING_STATES[number];
7	export type Signal = 'green' | 'amber' | 'red';
8	
9	/* Vận tốc góc hình thang: tăng dần – đều – giảm dần (a = phần thời gian tăng/giảm tốc) */
10	function trapezoidEase(u: number, a = 0.22) {
11	  u = clamp(u, 0, 1); const vmax = 1 / (1 - a);
12	  if (u < a) return vmax * u * u / (2 * a);
13	  if (u < 1 - a) return vmax * (u - a / 2);
14	  return 1 - vmax * (1 - u) * (1 - u) / (2 * a);
15	}
16	export class SwingController extends EventTarget {
17	  cfg: SongHanConfig;
18	  state: SwingState = 'CLOSED';
19	  t = 0;
20	  speed = 30;                     // hệ số tăng tốc so với thời gian thật
21	  angle = 0; lift = 0; pin = 1; barrier = 0;
22	  signal: Signal = 'green';
23	  closeAsked = false;
24	  fromTour = false;               // quay do Tour kích hoạt: đóng ngay khi tàu buồm qua hết luồng
25	  spanClear: () => boolean = () => true;
26	  canClose: () => boolean = () => true;
27	  canStart: () => boolean = () => true;     // thời tiết (bão) gán predicate; false → start() từ chối và phát 'swingBlocked'
28	
29	  constructor(cfg: SongHanConfig) {
30	    super();
31	    this.cfg = cfg;
32	  }
33	  get busy() { return this.state !== 'CLOSED'; }
34	  get allowEntry() { return this.state === 'CLOSED' || (this.state === 'REOPEN_TRAFFIC' && this.signal === 'green'); }
35	  start(speed?: number) {
36	    if (this.state !== 'CLOSED') return false;
37	    if (!this.canStart()) { this.dispatchEvent(new Event('swingBlocked')); return false; }
38	    if (speed) this.speed = speed;
39	    this.go('STOP_TRAFFIC'); this.dispatchEvent(new Event('swingStart'));
40	    return true;
41	  }
42	  requestClose() { if (this.state === 'OPEN') this.closeAsked = true; }
43	  go(s: SwingState) {
44	    this.state = s; this.t = 0;
45	    if (s === 'OPEN') this.closeAsked = false;
46	    this.dispatchEvent(new CustomEvent<SwingState>('stateChange', { detail: s }));
47	    if (s === 'OPEN') this.dispatchEvent(new Event('swingOpen'));
48	    if (s === 'CLOSED') this.dispatchEvent(new Event('swingClosed'));
49	  }
50	  update(dt: number) {
51	    if (this.state === 'CLOSED') return;
52	    const T = this.cfg.timing, rot = Math.PI / 2 * this.cfg.rotateDir;
53	    this.t += dt * this.speed;
54	    const k = (d: number) => clamp(this.t / d, 0, 1);
55	    switch (this.state) {
56	      case 'STOP_TRAFFIC':
57	        this.signal = this.t < T.amber ? 'amber' : 'red';
58	        this.barrier = smooth(clamp((this.t - T.amber) / T.barrier, 0, 1));
59	        if (this.t > T.amber + T.barrier && (this.spanClear() || this.t > T.stopMax)) this.go('UNLOCK');
60	        break;
61	      case 'UNLOCK': {            // rút chốt rồi nâng nhẹ nhịp khỏi gối đầu cánh
62	        const u = k(T.unlock);
63	        this.pin = 1 - smooth(clamp(u * 2, 0, 1)); this.lift = smooth(clamp(u * 2 - 1, 0, 1)) * this.cfg.lift;
64	        if (u >= 1) this.go('ROTATING_OPEN');
65	        break;
66	      }
67	      case 'ROTATING_OPEN':
68	        this.angle = trapezoidEase(k(T.rotate)) * rot;
69	        if (k(T.rotate) >= 1) this.go('OPEN');
70	        break;
71	      case 'OPEN':
72	        if ((this.t > T.openHold || this.closeAsked) && this.canClose()) this.go('ROTATING_CLOSE');
73	        break;
74	      case 'ROTATING_CLOSE':
75	        this.angle = (1 - trapezoidEase(k(T.rotate))) * rot;
76	        if (k(T.rotate) >= 1) { this.angle = 0; this.go('LOCK'); }
77	        break;
78	      case 'LOCK': {              // hạ nhịp xuống gối rồi đẩy chốt khóa
79	        const u = k(T.lock);
80	        this.lift = (1 - smooth(clamp(u * 2, 0, 1))) * this.cfg.lift; this.pin = smooth(clamp(u * 2 - 1, 0, 1));
81	        if (u >= 1) this.go('REOPEN_TRAFFIC');
82	        break;
83	      }
84	      case 'REOPEN_TRAFFIC':
85	        this.barrier = 1 - smooth(k(T.barrier));
86	        this.signal = this.t >= T.barrier ? 'green' : 'red';
87	        if (this.t > T.barrier + 2) { this.barrier = 0; this.signal = 'green'; this.go('CLOSED'); }
88	        break;
89	    }
90	  }
91	}
